+        }
+        applyFilter();
+    }
+
+    private static CustomerFilter filterFromQuery(QueryParameters queryParameters) {
+        String name = queryParameters.getSingleParameter("name").orElse("");
+        Set<CustomerStatus> statuses = queryParameters.getSingleParameter("status")
+                .map(CustomerListView::parseStatuses)
+                .orElse(Set.of());
+        return new CustomerFilter(name, statuses);
+    }
+
+    private static Set<CustomerStatus> parseStatuses(String rawValue) {
+        Set<CustomerStatus> statuses = new LinkedHashSet<>();
+        for (String part : rawValue.split(",")) {
+            if (!part.isBlank()) {
+                statuses.add(CustomerStatus.valueOf(part));
+            }
+        }
+        return statuses;
+    }
