+/**
+ * Verifies, in a real (headless) browser, the two things Karibu-Testing cannot
+ * see: the address bar and how many server round trips typing costs.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @BeforeAll
+    static void setupPlaywright() {
+        AbstractBasePlaywrightIT.setup();
+    }
+
+    @AfterAll
+    static void cleanupPlaywright() {
+        AbstractBasePlaywrightIT.cleanup();
+    }
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Test
+    void typingUpdatesUrlWithoutOneQueryPerKeystroke() {
+        Locator nameInput = page.locator("vaadin-text-field input");
+        nameInput.pressSequentially("aaltonen", new Locator.PressSequentiallyOptions().setDelay(40));
+
+        page.waitForCondition(() -> page.url().contains("name=aaltonen"));
+        assertTrue(page.url().contains("name=aaltonen"), "Address bar should carry the name filter: " + page.url());
+
+        Locator grid = page.locator("vaadin-grid");
+        assertTrue(grid.isVisible());
+    }
+
+    @Test
+    void openingUrlWithParametersPrefillsFields() {
+        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");
+        page.waitForLoadState();
+
+        Locator nameInput = page.locator("vaadin-text-field input");
+        assertEquals("vir", nameInput.inputValue());
+
+        Locator summary = page.getByText("Showing", new com.microsoft.playwright.Page.GetByTextOptions());
+        page.waitForCondition(() -> summary.textContent() != null && summary.textContent().startsWith("Showing"));
+        assertEquals("Showing 10 of 500", summary.textContent());
+    }
+
+    @Test
+    void changingFilterDoesNotPushNewHistoryEntries() {
+        page.navigate(getUrl());
+        page.waitForLoadState();
+        long historyLengthBefore = ((Number) page.evaluate("() => window.history.length")).longValue();
+
+        Locator nameInput = page.locator("vaadin-text-field input");
+        nameInput.pressSequentially("a", new Locator.PressSequentiallyOptions().setDelay(40));
+        nameInput.pressSequentially("d", new Locator.PressSequentiallyOptions().setDelay(40));
+        nameInput.pressSequentially("a", new Locator.PressSequentiallyOptions().setDelay(40));
+        page.waitForCondition(() -> page.url().contains("name=ada"));
+
+        long historyLengthAfter = ((Number) page.evaluate("() => window.history.length")).longValue();
+        assertEquals(historyLengthBefore, historyLengthAfter,
+                "Filtering must update the URL in place, not push a new history entry");
+    }
+}
